CREATE TRIGGER trg_request_logs_superseded_ai
         AFTER INSERT ON proxy_request_logs
         BEGIN
             UPDATE proxy_request_logs
             SET superseded_by = (SELECT proxy_dedup.request_id
          FROM proxy_request_logs proxy_dedup
          WHERE COALESCE(proxy_dedup.data_source, 'proxy') = 'proxy'
                  AND proxy_dedup.app_type = proxy_request_logs.app_type
                  AND proxy_dedup.status_code >= 200
                  AND proxy_dedup.status_code < 300
                  AND proxy_dedup.input_tokens = proxy_request_logs.input_tokens
                  AND proxy_dedup.output_tokens = proxy_request_logs.output_tokens
                  AND proxy_dedup.cache_read_tokens = proxy_request_logs.cache_read_tokens
                  AND (
                      proxy_dedup.cache_creation_tokens = proxy_request_logs.cache_creation_tokens
                      OR (
                          proxy_request_logs.cache_creation_tokens = 0
                          AND COALESCE(proxy_request_logs.data_source, 'proxy') IN ('codex_session', 'gemini_session', 'opencode_session')
                      )
                  )
                  AND proxy_dedup.created_at BETWEEN
                      proxy_request_logs.created_at - 600
                      AND proxy_request_logs.created_at + 600
                  AND (
                      LOWER(proxy_dedup.model) = LOWER(proxy_request_logs.model)
                      OR LOWER(proxy_dedup.model) = 'unknown'
                      OR LOWER(proxy_request_logs.model) = 'unknown'
                  )
          LIMIT 1)
             WHERE superseded_by = NEW.request_id;
             UPDATE proxy_request_logs
             SET superseded_by = (SELECT proxy_dedup.request_id
          FROM proxy_request_logs proxy_dedup
          WHERE COALESCE(proxy_dedup.data_source, 'proxy') = 'proxy'
                  AND proxy_dedup.app_type = NEW.app_type
                  AND proxy_dedup.status_code >= 200
                  AND proxy_dedup.status_code < 300
                  AND proxy_dedup.input_tokens = NEW.input_tokens
                  AND proxy_dedup.output_tokens = NEW.output_tokens
                  AND proxy_dedup.cache_read_tokens = NEW.cache_read_tokens
                  AND (
                      proxy_dedup.cache_creation_tokens = NEW.cache_creation_tokens
                      OR (
                          NEW.cache_creation_tokens = 0
                          AND COALESCE(NEW.data_source, 'proxy') IN ('codex_session', 'gemini_session', 'opencode_session')
                      )
                  )
                  AND proxy_dedup.created_at BETWEEN
                      NEW.created_at - 600
                      AND NEW.created_at + 600
                  AND (
                      LOWER(proxy_dedup.model) = LOWER(NEW.model)
                      OR LOWER(proxy_dedup.model) = 'unknown'
                      OR LOWER(NEW.model) = 'unknown'
                  )
          LIMIT 1)
             WHERE request_id = NEW.request_id AND COALESCE(NEW.data_source, 'proxy') IN ('session_log', 'codex_session', 'gemini_session', 'opencode_session');
             UPDATE proxy_request_logs
         SET superseded_by = NEW.request_id
         WHERE superseded_by IS NULL
           AND COALESCE(proxy_request_logs.data_source, 'proxy') IN ('session_log', 'codex_session', 'gemini_session', 'opencode_session')
           AND proxy_request_logs.created_at BETWEEN
               NEW.created_at - 600
               AND NEW.created_at + 600
           AND COALESCE(NEW.data_source, 'proxy') = 'proxy'
                  AND NEW.app_type = proxy_request_logs.app_type
                  AND NEW.status_code >= 200
                  AND NEW.status_code < 300
                  AND NEW.input_tokens = proxy_request_logs.input_tokens
                  AND NEW.output_tokens = proxy_request_logs.output_tokens
                  AND NEW.cache_read_tokens = proxy_request_logs.cache_read_tokens
                  AND (
                      NEW.cache_creation_tokens = proxy_request_logs.cache_creation_tokens
                      OR (
                          proxy_request_logs.cache_creation_tokens = 0
                          AND COALESCE(proxy_request_logs.data_source, 'proxy') IN ('codex_session', 'gemini_session', 'opencode_session')
                      )
                  )
                  AND NEW.created_at BETWEEN
                      proxy_request_logs.created_at - 600
                      AND proxy_request_logs.created_at + 600
                  AND (
                      LOWER(NEW.model) = LOWER(proxy_request_logs.model)
                      OR LOWER(NEW.model) = 'unknown'
                      OR LOWER(proxy_request_logs.model) = 'unknown'
                  );
         END;
